import {grant} from './research.mjs?v=4.9a';
export function extendNozzle(L){L.printerControls.push({id:'motor',x:1350,y:480,label:'供給モーター 正転・停止・逆転'},{id:'heater',x:1550,y:480,label:'ノズル温調'},{id:'pull',x:1700,y:480,label:'詰まりをつかむ'});}
export function initNozzle(g){g.printer.nozzle={motor:0,heat:false,temp:20,pulling:false,amount:0,done:false};}
export function nozzleAction(g,id){const n=g.printer.nozzle;if(id==='motor'){n.motor=n.motor===0?1:n.motor===1?-1:0;return true;}if(id==='heater'){n.heat=!n.heat;return true;}if(id==='pull'){if(n.motor===-1&&n.temp>=50&&n.temp<=70&&!n.done)n.pulling=true;return true;}return false;}
export function tickNozzle(g,dt){const n=g.printer.nozzle;if(!g.printer.chase.done||n.done)return;n.temp+=Math.sign((n.heat?60:20)-n.temp)*Math.min(Math.abs((n.heat?60:20)-n.temp),dt*20);if(n.pulling&&(g.rooms.active!=='B'||n.motor!==-1||n.temp<50||n.temp>70||g.player.y<420||g.player.y>510||Math.abs(g.player.x-1640)>220)){n.pulling=false;n.amount=0;}if(n.pulling){n.amount=Math.max(n.amount,Math.min(1,(1700-g.player.x-14)/110));if(n.amount>=1){n.done=true;n.pulling=false;grant(g,20,'ノズル復旧',1700,430);g.events.push({type:'repairComplete',x:1700,y:450,text:'NOZZLE CLEAR'});}}}
export function drawNozzle(c,g){if(g.rooms?.active!=='B')return;const n=g.printer.nozzle;c.save();c.fillStyle='#8da7b2';c.fillRect(1640,320,120,65);c.fillStyle=n.done?'#90e9c5':'#e0a0be';c.fillRect(1665,340,70,20);c.fillStyle='#e6c597';c.beginPath();c.moveTo(1660,385);c.lineTo(1740,385);c.lineTo(1700,435);c.fill();c.font='bold 16px monospace';c.textAlign='center';c.fillStyle='#d5eee3';c.fillText(n.done?'EXTRUDING':Math.round(n.temp)+'°  '+(n.motor<0?'↶':n.motor>0?'↷':'■'),1700,300);c.strokeStyle='#f0b68e';c.lineWidth=5;c.beginPath();c.moveTo(1700,430);c.lineTo(n.pulling?g.player.x+14:1700,n.pulling?g.player.y+20:470);c.stroke();if(n.done){c.strokeStyle='#f2c59a';c.lineWidth=7;c.beginPath();c.moveTo(1700,435);c.lineTo(1700,460+(g.time*30)%30);c.stroke();}if(!n.done){c.fillStyle='#bc9aab';c.fillRect(n.pulling?g.player.x+4:1690,n.pulling?g.player.y+15:454,20,20);}c.restore();}
